begin _pocket_fightmodule

float timer

if(pocket_fightstage == 1)
	set timer to (timer + GetSecondsPassed)
	if(timer > 5)
		set timer to 0
		set pocket_hiding to Random, 5
		if(pocket_hiding == 0)
			if("_pocket_chair1".isdestroyed == 1)
				set pocket_hiding to 1
			endif
		endif
		if(pocket_hiding == 1)
			if("_pocket_chair2".isdestroyed == 1)
				set pocket_hiding to 2
			endif
		endif
		if(pocket_hiding == 2)
			if("_pocket_shelf1".isdestroyed == 1)
				set pocket_hiding to 3
			endif
		endif
		if(pocket_hiding == 3)
			if("_pocket_shelf2".isdestroyed == 1)
				set pocket_hiding to 4
			endif
		endif
		if(pocket_hiding == 4)
			if("_pocket_table".isdestroyed == 1)
				set pocket_hiding to 0
			endif
		endif

		if(pocket_hiding == 0)
			if("_pocket_chair1".isdestroyed == 1)
				set pocket_hiding to 1
			endif
		endif
		if(pocket_hiding == 1)
			if("_pocket_chair2".isdestroyed == 1)
				set pocket_hiding to 2
			endif
		endif
		if(pocket_hiding == 2)
			if("_pocket_shelf1".isdestroyed == 1)
				set pocket_hiding to 3
			endif
		endif
		if(pocket_hiding == 3)
			if("_pocket_shelf2".isdestroyed == 1)
				set pocket_hiding to 4
			endif
		endif
	endif
endif

end

begin _power_questexplode1

short doonce

if(GameHour > 9.5)
	set doonce to 0
endif

if(GameHour < 9)
	set doonce to 0
endif

if( GetJournalIndex SSE_power < 90)
	if(GameHour >= 9.001)
		if(GameHour < 9.5)
			if(doonce == 0)
				PlaceAtMe, "power_exploderQuest", 1, 1, 1
				set doonce to 1
			endif
		endif
	endif
endif


end

